#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/closed_loop_outcome_v18_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/opportunity_execution_capability_bridge.py "$BK/" 2>/dev/null || true
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/closed_loop_outcome_evaluator.py
echo "" | base64 -d > "$PREFIX/tmp/companyos_outcome_bridge_patch.py"
python "$PREFIX/tmp/companyos_outcome_bridge_patch.py"
rm -f "$PREFIX/tmp/companyos_outcome_bridge_patch.py"

echo "" | base64 -d > "$PREFIX/tmp/companyos_outcome_supervisor_patch.py"
python "$PREFIX/tmp/companyos_outcome_supervisor_patch.py"
rm -f "$PREFIX/tmp/companyos_outcome_supervisor_patch.py"

echo "" | base64 -d > scripts/companyos_outcomectl
chmod +x scripts/companyos_outcomectl
echo "" | base64 -d > tests/test_closed_loop_outcome_evaluator_v18.py

echo "[1/8] Compile"
python -m py_compile companyos/runtime/closed_loop_outcome_evaluator.py companyos/runtime/opportunity_execution_capability_bridge.py companyos/runtime/service_supervisor.py tests/test_closed_loop_outcome_evaluator_v18.py

echo "[2/8] Outcome evaluator tests"
python -m unittest tests.test_closed_loop_outcome_evaluator_v18 -v

echo "[3/8] Rebuild one action packet with baseline metrics"
scripts/companyos_actionbridgectl once || true

echo "[4/8] Run evaluator"
scripts/companyos_outcomectl once | tee .companyos_runtime/closed_loop_outcome_v18_first_cycle.json || true

echo "[5/8] Show evaluator status"
scripts/companyos_outcomectl status || true

echo "[6/8] Commit/push"
git add companyos/runtime/closed_loop_outcome_evaluator.py companyos/runtime/opportunity_execution_capability_bridge.py companyos/runtime/service_supervisor.py scripts/companyos_outcomectl tests/test_closed_loop_outcome_evaluator_v18.py
git diff --cached --quiet || git commit -m "Add closed-loop outcome evaluation for capability-guided execution"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[7/8] Restart"
scripts/companyosctl restart || true
sleep 8

echo "[8/8] Verify"
echo "===== OUTCOME EVALUATOR ====="
scripts/companyos_outcomectl status || true
echo "===== ACTION BRIDGE ====="
scripts/companyos_actionbridgectl status || true
echo "===== FEEDBACK ====="
scripts/companyos_feedbackctl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CLOSED_LOOP_OUTCOME_LEARNING_V18=PASS"
